contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData) public payable {
        require(address(this).balance >= 0);
        address optimistic = address(c.optimisticAsserter());

        bool revertedFromNonAsserter;
        try c.requestPrice(identifier, time, ancillaryData) {
            revertedFromNonAsserter = false;
        } catch {
            revertedFromNonAsserter = true;
        }

        bool revertedFromAsserter;
        if (optimistic.code.length > 0) {
            (bool success, ) = optimistic.call(
                abi.encodeWithSignature(
                    "requestPrice(bytes32,uint256,bytes,(uint256,uint8,uint8,uint8,uint256,uint256,uint256),
                    identifier,
                    time,
                    ancillaryData,
                    0,
                    0,
                    0,
                    0,
                    0,
                    0
                )
            );
            revertedFromAsserter = !success;
        } else {
            revertedFromAsserter = false;
        }

        assert(revertedFromNonAsserter == (msg.sender != optimistic) || revertedFromAsserter);
    }

    receive() external payable {}
}

